<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="text-2xl font-bold text-slate-900">Data Pelanggan</h1><p class="mt-1 text-sm text-slate-500">Kelola dan pantau informasi pelanggan Tirtanadi.</p></div><?php if (Auth::isAdmin()): ?><a href="<?= e(url('/pelanggan/create')) ?>" class="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/15 hover:bg-primary-dark"><span class="text-lg">+</span> Tambah Pelanggan</a><?php endif; ?></section>
<section class="rounded-2xl bg-white p-4 shadow-card sm:p-6"><form class="grid gap-3 md:grid-cols-[1fr_180px_auto]" method="get"><label class="sr-only" for="q">Cari pelanggan</label><div class="relative"><span class="absolute left-3 top-3 text-slate-400">⌕</span><input id="q" name="q" value="<?= e($search) ?>" class="form-input pl-9" placeholder="Cari NPA, nama, atau alamat"></div><select name="status" class="form-input"><option value="">Semua status</option><?php foreach (['Aktif','Nonaktif','Putus'] as $option): ?><option value="<?= e($option) ?>" <?= $status === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select><div class="flex gap-2"><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white hover:bg-primary-dark">Cari</button><a href="<?= e(url('/pelanggan')) ?>" class="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-600 hover:bg-slate-50">Reset</a></div></form>
    <div class="mt-6 overflow-hidden rounded-xl border border-slate-100"><?php if ($data['rows']): ?><div class="table-wrap"><table class="w-full min-w-[860px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">No</th><th class="px-5 py-3">NPA</th><th class="px-5 py-3">Pelanggan</th><th class="px-5 py-3">Alamat</th><th class="px-5 py-3">Telepon</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($data['rows'] as $i => $item): $kategori = kategoriStatus($item); ?><tr class="hover:bg-slate-50/70"><td class="px-5 py-4 text-slate-500"><?= (($data['page'] - 1) * $data['per_page']) + $i + 1 ?></td><td class="px-5 py-4 font-mono text-xs font-semibold text-primary"><?= e($item['npa']) ?></td><td class="px-5 py-4 font-semibold text-slate-800"><?= e($item['nama_pelanggan']) ?></td><td class="max-w-xs truncate px-5 py-4 text-slate-600" title="<?= e($item['alamat']) ?>"><?= e($item['alamat']) ?></td><td class="px-5 py-4 text-slate-600"><?= e($item['no_telepon'] ?: '—') ?></td><td class="px-5 py-4"><span class="badge badge-<?= $kategori['key'] === 'aktif' ? 'disetujui' : ($kategori['key'] === 'nonaktif_lama' ? 'ditolak' : 'pending') ?>"><?= e($kategori['label']) ?></span></td><td class="px-5 py-4 text-right"><a href="<?= e(url('/pelanggan/' . rawurlencode($item['npa']))) ?>" class="font-semibold text-primary hover:underline">Detail</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Belum ada data pelanggan'; $emptyText='Tambahkan pelanggan baru atau ubah kata kunci pencarian.'; require root_path('app/Views/components/empty-state.php'); endif; ?></div><?php require root_path('app/Views/components/pagination.php'); ?></section>
